-- Divas Skin Care · 2026-10-16 · Fajas Fájate bajo pedido (catálogo de Louie, PRESUPUESTO 2026-8)
-- Ejecutar en Supabase (proyecto Divas) → SQL Editor. Se puede ejecutar varias veces.
alter table public.stock add column if not exists bajo_pedido boolean not null default false;
alter table public.stock add column if not exists descripcion text;
alter table public.stock add column if not exists tallas text;
alter table public.stock add column if not exists colores text;
alter table public.stock add column if not exists referencia text;
drop view if exists public.tienda_web;
create view public.tienda_web as
  select id, nombre, marca, precio, imagen_url, (coalesce(cantidad,0) > 0) as disponible,
         bajo_pedido, descripcion, tallas, colores, referencia
  from public.stock where visible_web = true;
grant select on public.tienda_web to anon, authenticated;
update public.stock set nombre='Faja postquirúrgica de primera postura con control medio y efecto moldeador', marca='Fájate', precio=134.0, imagen_url='img/fajate/fajate-11354.jpg', visible_web=true, bajo_pedido=true, descripcion='La Faja de Primera Postura es ideal para la recuperación postquirúrgica, eliminando fluidos y reduciendo la inflamación. Usada 24 horas al día en las primeras semanas, luego puede ser adaptada a uso nocturno o diario. Su diseño de manga sisa y busto libre moldea la espalda y controla el tejido adiposo. Con broches graduables y cierre perineal para mayor comodidad, moldea cintura, piernas y caderas, realzando los glúteos. Las costuras planas aseguran confort, siendo perfecta para postquirúrgico, postparto o uso diario. Compresión: mediana.', tallas='XS-3XL', colores='Café' where referencia='11354';
insert into public.stock (nombre, marca, sku, referencia, cantidad, coste, precio, tipo_impuesto, porcentaje_impuesto, visible_web, imagen_url, bajo_pedido, descripcion, tallas, colores) select 'Faja postquirúrgica de primera postura con control medio y efecto moldeador', 'Fájate', 'FJ-11354', '11354', 0, 0, 134.0, 'IGIC', 0, true, 'img/fajate/fajate-11354.jpg', true, 'La Faja de Primera Postura es ideal para la recuperación postquirúrgica, eliminando fluidos y reduciendo la inflamación. Usada 24 horas al día en las primeras semanas, luego puede ser adaptada a uso nocturno o diario. Su diseño de manga sisa y busto libre moldea la espalda y controla el tejido adiposo. Con broches graduables y cierre perineal para mayor comodidad, moldea cintura, piernas y caderas, realzando los glúteos. Las costuras planas aseguran confort, siendo perfecta para postquirúrgico, postparto o uso diario. Compresión: mediana.', 'XS-3XL', 'Café' where not exists (select 1 from public.stock where referencia='11354');
update public.stock set nombre='Faja postquirúrgica a la rodilla y mangas con control medio fit 360', marca='Fájate', precio=145.0, imagen_url='img/fajate/fajate-11353.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja postquirúrgica ideal para las primeras semanas de recuperación. Ofrece control moderado, ayuda en la eliminación de fluidos y desinflamación, y es perfecta para cirugías de espalda y brazos. Su diseño fit 360 moldea glúteos y se adapta a caderas amplias. Con cierre perineal y cargaderas ajustables para comodidad durante el uso. Tela que proporciona un ajuste seguro y confortable, recomendado para uso las 24 horas según indicación médica. Compresión: mediana.', tallas='XS-3XL', colores='Café' where referencia='11353';
insert into public.stock (nombre, marca, sku, referencia, cantidad, coste, precio, tipo_impuesto, porcentaje_impuesto, visible_web, imagen_url, bajo_pedido, descripcion, tallas, colores) select 'Faja postquirúrgica a la rodilla y mangas con control medio fit 360', 'Fájate', 'FJ-11353', '11353', 0, 0, 145.0, 'IGIC', 0, true, 'img/fajate/fajate-11353.jpg', true, 'Faja postquirúrgica ideal para las primeras semanas de recuperación. Ofrece control moderado, ayuda en la eliminación de fluidos y desinflamación, y es perfecta para cirugías de espalda y brazos. Su diseño fit 360 moldea glúteos y se adapta a caderas amplias. Con cierre perineal y cargaderas ajustables para comodidad durante el uso. Tela que proporciona un ajuste seguro y confortable, recomendado para uso las 24 horas según indicación médica. Compresión: mediana.', 'XS-3XL', 'Café' where not exists (select 1 from public.stock where referencia='11353');
update public.stock set nombre='Faja postquirúrgica de alta compresión con ajuste en broches y cobertura completa', marca='Fájate', precio=168.0, imagen_url='img/fajate/fajate-11347.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja Postquirúrgica y Postparto con Brasier, diseñada para brindar soporte y comodidad en la recuperación. Con copas de alto cubrimiento y un orificio para copas de recolección de leche, facilita la lactancia. Su exterior en powernet ofrece control firme, mientras que la lycra interna aporta suavidad. Esta faja modela y realza glúteos con tecnología Cola Fit 360 y proporciona cubrimiento en espalda, brazos y busto. Incluye abrochadura de 3 niveles, cierre perineal y largo a la rodilla, combinando comodidad y soporte en una sola prenda. Compresión: alta.', tallas='XS-3XL', colores='Café' where referencia='11347';
insert into public.stock (nombre, marca, sku, referencia, cantidad, coste, precio, tipo_impuesto, porcentaje_impuesto, visible_web, imagen_url, bajo_pedido, descripcion, tallas, colores) select 'Faja postquirúrgica de alta compresión con ajuste en broches y cobertura completa', 'Fájate', 'FJ-11347', '11347', 0, 0, 168.0, 'IGIC', 0, true, 'img/fajate/fajate-11347.jpg', true, 'Faja Postquirúrgica y Postparto con Brasier, diseñada para brindar soporte y comodidad en la recuperación. Con copas de alto cubrimiento y un orificio para copas de recolección de leche, facilita la lactancia. Su exterior en powernet ofrece control firme, mientras que la lycra interna aporta suavidad. Esta faja modela y realza glúteos con tecnología Cola Fit 360 y proporciona cubrimiento en espalda, brazos y busto. Incluye abrochadura de 3 niveles, cierre perineal y largo a la rodilla, combinando comodidad y soporte en una sola prenda. Compresión: alta.', 'XS-3XL', 'Café' where not exists (select 1 from public.stock where referencia='11347');
update public.stock set nombre='Faja postquirúrgica con brasier hasta la rodilla de alta compresión', marca='Fájate', precio=154.0, imagen_url='img/fajate/fajate-11366.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja postquirúrgica de alta compresión ideal para cicatrización y recuperación. Fabricada con powernet externo y lycra interna, ofrece beneficios para la piel, control de espalda y ajuste personalizado con abrochadura de 3 niveles y 19 ganchos para mejorar la postura. Perfecta para uso diario y postcirugía, casi invisible bajo la ropa. Incluye refuerzo abdominal para un control firme, cierre perineal para comodidad y diseño de cola fit 360 para moldear glúteos. Con delicado encaje en el ruedo, es una excelente opción para cirugías de espalda y brazos. Compresión: alta.', tallas='XS-3XL', colores='Café' where referencia='11366';
