update public.stock set nombre='Faja postquirúrgica media pierna con brasier y cierre lateral de alta compresión', marca='Fájate', precio=164.0, imagen_url='img/fajate/fajate-11375.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja postquirúrgica de alta compresión con brasier, cremallera lateral y broches internos para un ajuste seguro. Su capa externa en powernet proporciona control firme, mientras que la lycra interna cuida la piel, moldeando cintura y glúteos con el diseño de cola fit 360. Ideal para recuperación postoperatoria y postparto, mejora la cicatrización y la postura. Las costuras planas protegen la piel, y los broches facilitan la lactancia y la asepsia. Compresión: alta.', tallas='XS-3XL', colores='Café' where referencia='11375';
