update public.stock set nombre='Faja postquirúrgica media pierna con brasier de alta compresión', marca='Fájate', precio=154.0, imagen_url='img/fajate/fajate-11215.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja Postquirúrgica de Alta Compresión con Brasier y Estilo Media Pierna. Ideal para recuperación, cicatrización y postparto, moldea la cintura, glúteos y busto. Su abrochadura de 3 niveles asegura un ajuste perfecto y proporciona soporte para una postura mejorada. El refuerzo abdominal y el cubrimiento de la espalda garantizan una compresión óptima y un vientre liso. Con costuras planas para mayor confort, esta faja también facilita la lactancia y la asepsia en cirugías estéticas. 100% forrada para ofrecerte bienestar total durante todo el proceso de recuperación. Compresión: alta.', tallas='XS-5XL', colores='Café-Negro' where referencia='11215';
