update public.stock set nombre='Faja postquirúrgica de alta compresión media pierna con triple refuerzo abdominal y busto libre', marca='Fájate', precio=121.55, imagen_url='img/fajate/fajate-11111.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja postquirúrgica de busto libre con ajuste de tres niveles que moldea caderas, cintura, espalda y abdomen. Su triple refuerzo abdominal y largo a media pierna ofrecen comodidad y compresión ideal. Cargaderas ajustables. Fabricada con powernet de alta compresión y lycra enriquecida con microcápsulas Viveltex para cuidar la piel. Sus costuras planas brindan confort, siendo perfecta para uso postquirúrgico, postparto o diario, definiendo y estilizando la figura. Compresión: alta.', tallas='M-6XL', colores='Café-Negro' where referencia='11111';
