update public.stock set nombre='Faja postquirúrgica Fit 360 cachetera de alta compresión y realce de glúteos', marca='Fájate', precio=137.9, imagen_url='img/fajate/fajate-11380.jpg', visible_web=true, bajo_pedido=true, descripcion='La faja postquirúrgica de alta compresión controla abdomen, caderas, espalda y glúteos, favoreciendo la recuperación postoperatoria. Con cargaderas graduables y tres niveles de ajuste, ofrece un ajuste personalizado y alivia dolores lumbares. Su encaje siliconado garantiza sujeción firme y cómoda. El color cocoa asegura discreción bajo la ropa, mientras que el diseño Cola Fit 360 realza los glúteos. Además, el cierre perineal facilita el uso diario, brindando confort y practicidad durante todo el día. Compresión: alta.', tallas='S-6XL', colores='Café' where referencia='11380';
