update public.stock set nombre='Faja postquirúrgica a la rodilla con abrochadura de tres niveles y control abdominal', marca='Fájate', precio=156.0, imagen_url='img/fajate/fajate-11043.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja postquirúrgica de busto libre con cargaderas ajustables, ideal para moldear abdomen, cintura, muslos, espalda y glúteos. Ajuste de tres niveles, cierre perineal y doble refuerzo abdominal para mayor comodidad y reducción de medidas. Largo a la rodilla que estiliza piernas, realza glúteos y tela interna de lycra con propiedades cicatrizantes. Costuras planas y detalle de encaje en el ruedo, perfecta para uso postoperatorio, postparto y diario. Compresión: alta.', tallas='XL-5XL', colores='Café' where referencia='11043';
