insert into public.stock (nombre, marca, sku, referencia, cantidad, coste, precio, tipo_impuesto, porcentaje_impuesto, visible_web, imagen_url, bajo_pedido, descripcion, tallas, colores) select 'Faja tipo panty media pierna de alta compresión y realce de glúteo', 'Fájate', 'FJ-11346', '11346', 0, 0, 99.99, 'IGIC', 0, true, 'img/fajate/fajate-11346.jpg', true, 'La faja panty moldea cintura, espalda y caderas en 360°, ofreciendo una silueta definida. Su diseño de tiro alto y ajuste con abrochadura mejora la postura, mientras que el cierre perineal brinda comodidad. Realza los glúteos de forma natural y asegura un ajuste perfecto con encaje elástico y silicona. Forrada con lycra y microcápsulas, cuida la piel mientras define caderas y glúteos. Compresión: alta.', 'XS-5XL', 'Café' where not exists (select 1 from public.stock where referencia='11346');
update public.stock set nombre='Faja trusa corta invisible de compresión media y realce de glúteos', marca='Fájate', precio=63.0, imagen_url='img/fajate/fajate-11075.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja tipo short de compresión media, ideal para resaltar las curvas de manera natural. Con diseño de busto libre, es perfecta para combinar con cualquier brasier y prenda exterior. Su tejido bidireccional moldea la figura suavemente, ofreciendo comodidad durante todo el día. El color cocoa se adapta fácilmente a cualquier outfit, siendo ideal para uso diario, postquirúrgico o durante procesos de reducción de peso. Cuenta con encaje elástico en el ruedo para un mejor ajuste y realce de los glúteos. Las costuras planas aseguran confort y control, proporcionando una figura esbelta y delicada sin marcas visibles bajo la ropa. Compresión: mediana.', tallas='S-3XL', colores='Café' where referencia='11075';
insert into public.stock (nombre, marca, sku, referencia, cantidad, coste, precio, tipo_impuesto, porcentaje_impuesto, visible_web, imagen_url, bajo_pedido, descripcion, tallas, colores) select 'Faja trusa corta invisible de compresión media y realce de glúteos', 'Fájate', 'FJ-11075', '11075', 0, 0, 63.0, 'IGIC', 0, true, 'img/fajate/fajate-11075.jpg', true, 'Faja tipo short de compresión media, ideal para resaltar las curvas de manera natural. Con diseño de busto libre, es perfecta para combinar con cualquier brasier y prenda exterior. Su tejido bidireccional moldea la figura suavemente, ofreciendo comodidad durante todo el día. El color cocoa se adapta fácilmente a cualquier outfit, siendo ideal para uso diario, postquirúrgico o durante procesos de reducción de peso. Cuenta con encaje elástico en el ruedo para un mejor ajuste y realce de los glúteos. Las costuras planas aseguran confort y control, proporcionando una figura esbelta y delicada sin marcas visibles bajo la ropa. Compresión: mediana.', 'S-3XL', 'Café' where not exists (select 1 from public.stock where referencia='11075');
update public.stock set nombre='Mentonera postquirúrgica facial con soporte ajustable y compresión', marca='Fájate', precio=65.0, imagen_url='img/fajate/fajate-11513.jpg', visible_web=true, bajo_pedido=true, descripcion='Mentonera postquirúrgica ideal para procedimientos faciales como estiramiento de rostro, levantamiento de cejas, liposucción en cara y cuello, cirugía maxilofacial, y más. Su diseño con ajuste de velcro en la parte superior permite un control personalizado según tus necesidades. Elaborada en powernet 100% con forro de algodón, esta mentonera ofrece soporte mejorado para mayor comodidad. Es ligera, transpirable y duradera, manteniéndote fresco y cómodo durante todo el día.', tallas='XS-L', colores='Café' where referencia='11513';
