update public.stock set nombre='Brasier postquirúrgico tipo top con soporte para recuperación de tejidos', marca='Fájate', precio=61.0, imagen_url='img/fajate/fajate-11027.jpg', visible_web=true, bajo_pedido=true, descripcion='Brasier postquirúrgico tipo top, ideal para recuperación tras cirugías, elaborado en lycra con microcápsulas que favorecen la piel y regeneran los tejidos. Su diseño sin arcos ni realce, con copa prehormada, asegura comodidad y soporte durante el día y la noche. Perfecto para lactancia, descanso o ejercicio, ofrece versatilidad para uso continuo. Con abrochadura frontal y cargaderas graduables, garantiza un ajuste personalizado y una sujeción adecuada gracias al elástico en la base.', tallas='32-42', colores='Café' where referencia='11027';
