update public.stock set nombre='Brasier postquirúrgico multifuncional con control del busto', marca='Fájate', precio=64.0, imagen_url='img/fajate/fajate-11065.jpg', visible_web=true, bajo_pedido=true, descripcion='Bra postquirúrgico sin aros, diseñado para mejorar la postura y controlar el busto. Refuerzo en X en la espalda para ajuste y mayor cubrimiento en copas, sisa y espalda. Incluye abrochadura frontal con 6 ganchos y cargaderas ajustables. Cómodo, liviano y seguro con banda elástica en la base.', tallas='32-42', colores='Café' where referencia='11065';
