update public.stock set nombre='Brasier postquirúrgico con control del busto y soporte para mejorar la postura', marca='Fájate', precio=68.1, imagen_url='img/fajate/fajate-11348.jpg', visible_web=true, bajo_pedido=true, descripcion='Bra Postquirúrgico sin aros diseñado para proporcionar óptima postura y control del busto desde el primer uso. Su refuerzo en X en la espalda y tela de alta compresión aseguran un ajuste firme y cómodo. La abrochadura frontal de 9 ganchos y el ajuste en los hombros facilitan la colocación y adaptabilidad. Ligero y funcional, este bra es ideal para postoperatorios de busto. Su banda elástica en la base ofrece soporte adicional, mientras que su diseño Fit 360 realza y define la figura, combinando comodidad y estilo para uso diario.', tallas='32-42', colores='Café' where referencia='11348';
