update public.stock set nombre='Faja masculina postquirúrgica de alta compresión y uso diario', marca='Fájate', precio=157.0, imagen_url='img/fajate/fajate-11016.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja masculina de control alto, perfecta para uso postquirúrgico y diario. Su tela externa asegura una compresión óptima en abdomen y cintura, mientras que la interna hidrata y nutre la piel, brindando beneficios para la recuperación postoperatoria y un efecto visual de hasta 2 cm menos. Con soporte lumbar, cierre frontal de ajuste fácil, y una abertura perineal que facilita su uso diario. Su diseño anatómico está pensado para ofrecer la máxima comodidad en cada uso. Compresión: alta.', tallas='S-3XL', colores='Café' where referencia='11016';
