update public.stock set nombre='Faja postquirúrgica abdominal con espuma y soporte ajustable', marca='Fájate', precio=75.0, imagen_url='img/fajate/fajate-11121.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja abdominal postoperatoria con espuma, ideal para la fase inicial postquirúrgica. Protege la piel, favorece la desinflamación y readherencia de la piel a la fascia muscular, promoviendo una cicatrización uniforme y sin marcas. Diseñada con compresión uniforme, esta faja actúa como un protector entre la piel y la prenda postquirúrgica. Fabricada en algodón, cuenta con ajuste en velcro y una tabla acrílica frontal para un soporte máximo y seguro.', tallas='XS-XL', colores='Café' where referencia='11121';
