update public.stock set nombre='Tabla abdominal postquirúrgica tipo pera para drenaje y prevención de fibrosis', marca='Fájate', precio=40.0, imagen_url='img/fajate/fajate-11146.jpg', visible_web=true, bajo_pedido=true, descripcion='Tabla abdominal postoperatoria ideal para acelerar el proceso de recuperación. Diseñada para drenar líquidos inflamatorios y prevenir la fibrosis, favorece la postura erguida, reduce el dolor y mejora la circulación al mantener presión. Elaborada en materiales de alta calidad, como acrílico, licra beneficiosa para la piel y espuma rígida, garantiza un ajuste perfecto para aliviar molestias, especialmente en la espalda durante posiciones prolongadas.', tallas='ÚNICA', colores='Café' where referencia='11146';
