update public.stock set nombre='Faja postquirúrgica a la rodilla con soporte abdominal y cubrimiento de espalda', marca='Fájate', precio=173.0, imagen_url='img/fajate/fajate-11355.jpg', visible_web=true, bajo_pedido=true, descripcion='Recupera tu confianza con la faja postquirúrgica a la rodilla de Fájate. Con soporte abdominal y ajuste personalizado, moldea tu figura y proporciona comodidad en cada uso. Fabricada en lycra forrada con microcápsulas Viveltex, estiliza 360° y levanta glúteos. Ideal para postparto o uso diario, sus costuras planas aseguran un ajuste perfecto y protección para tu piel. No dejes pasar la oportunidad de sentirte bien; esta faja es esencial para tu bienestar durante la recuperación. Compresión: alta.', tallas='XS-L', colores='Café' where referencia='11355';
