update public.stock set nombre='Faja postquirúrgica moldeadora a media pierna con busto libre y soporte', marca='Fájate', precio=146.0, imagen_url='img/fajate/fajate-11378.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja postquirúrgica moldeadora de alta compresión, controla abdomen, muslos, torso y caderas. Con cremallera lateral y broches internos para ajuste preciso, alivia dolores lumbares y promueve desinflamación. El doble refuerzo abdominal previene la retención de líquidos y acelera la cicatrización. Diseñada con encaje delicado, powernet exterior para moldeado y lycra interna que cuida la piel. Cola fit 360 realza los glúteos, y el cierre perineal mejora la comodidad. Ideal para recuperación postquirúrgica y uso diario. Compresión: alta.', tallas='XS-3XL', colores='Café' where referencia='11378';
