update public.stock set nombre='Panty moldeador hasta la rodilla con control medio y realce de glúteos', marca='Fájate', precio=90.0, imagen_url='img/fajate/fajate-11477.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja panty moldeadora de control medio, ideal para definir la figura desde el bajo busto hasta la rodilla. Fabricada con licra suave, realza las curvas y ofrece un doble control abdominal que estiliza y mantiene firme el abdomen. El elástico superior con silicona antideslizante asegura que la prenda se mantenga en su lugar durante todo el día. Esta faja es perfecta para disimular la celulitis, gracias a sus costuras planas que no irritan la piel. Además, moldea los glúteos para una apariencia redondeada y cuenta con un huevo perineal que facilita las idas al baño. Ideal para usar con vestidos, jeans o pantalones, proporcionando comodidad y estilo. Compresión: mediana.', tallas='XS-2XL', colores='Café' where referencia='11477';
insert into public.stock (nombre, marca, sku, referencia, cantidad, coste, precio, tipo_impuesto, porcentaje_impuesto, visible_web, imagen_url, bajo_pedido, descripcion, tallas, colores) select 'Panty moldeador hasta la rodilla con control medio y realce de glúteos', 'Fájate', 'FJ-11477', '11477', 0, 0, 90.0, 'IGIC', 0, true, 'img/fajate/fajate-11477.jpg', true, 'Faja panty moldeadora de control medio, ideal para definir la figura desde el bajo busto hasta la rodilla. Fabricada con licra suave, realza las curvas y ofrece un doble control abdominal que estiliza y mantiene firme el abdomen. El elástico superior con silicona antideslizante asegura que la prenda se mantenga en su lugar durante todo el día. Esta faja es perfecta para disimular la celulitis, gracias a sus costuras planas que no irritan la piel. Además, moldea los glúteos para una apariencia redondeada y cuenta con un huevo perineal que facilita las idas al baño. Ideal para usar con vestidos, jeans o pantalones, proporcionando comodidad y estilo. Compresión: mediana.', 'XS-2XL', 'Café' where not exists (select 1 from public.stock where referencia='11477');
update public.stock set nombre='Tabla postquirúrgica tipo mariposa', marca='Fájate', precio=40.0, imagen_url='img/fajate/fajate-11516.jpg', visible_web=true, bajo_pedido=true, descripcion='La Tabla Mariposa Postquirúrgica Lumbar es esencial para una recuperación cómoda tras una cirugía lumbar. Su diseño hipoalergénico alivia el dolor y mantiene una postura adecuada, previniendo la fibrosis y la retención de líquidos. Este producto innovador se adapta a tu cuerpo, promoviendo una recuperación más rápida. No esperes más para mejorar tu bienestar; elige la Tabla Mariposa y disfruta del confort que mereces en este momento crucial. Tu camino hacia una recuperación efectiva comienza aquí.', tallas='ÚNICA', colores='Café' where referencia='11516';
