update public.stock set nombre='Faja busto libre media pierna fit 360 alta compresión', marca='Fájate', precio=150.0, imagen_url='img/fajate/fajate-11540.jpg', visible_web=true, bajo_pedido=true, descripcion='Descubre la faja postquirúrgica busto libre media pierna Fit 360 de alta compresión. Ofrece control firme en abdomen, espalda y caderas, gracias a su triple refuerzo y tela Power que moldean tu silueta. Con abertura perineal para mayor comodidad y encaje siliconado que evita que se enrolle, es perfecta para realzar tus curvas. Su color cocoa aporta discreción bajo la ropa. No esperes más, adquiere la faja que te hará sentir segura y cómoda. ¡Compra ahora y transforma tu recuperación! Compresión: alta.', tallas='XS-2XL', colores='Café' where referencia='11540';
