update public.stock set nombre='Faja masculina de control medio en Power y lycra que moldea todo el cuerpo', marca='Fájate', precio=145.0, imagen_url='img/fajate/fajate-11526.jpg', visible_web=true, bajo_pedido=true, descripcion='Faja masculina de control medio moldea el abdomen, la cintura y la espalda con comodidad. Confeccionada en Power y lycra de alta resistencia, brinda control firme y libertad de movimiento. Sus cargaderas anchas ofrecen soporte sin presión, y su forro interno suave asegura confort durante todo el día. Cuenta con abrochadura frontal de tres niveles, abertura perineal funcional y diseño anatómico de media pierna que moldea glúteos y muslos. Ideal para uso diario, brinda una silueta firme, definida y natural. Compresión: mediana.', tallas='S-3XL', colores='Negro' where referencia='11526';
